import React from "react";

const TaskInput = ({ quadrant, addTask, taskInputs, setTaskInputs }) => {
  const handleInputChange = (e) => {
    setTaskInputs({ ...taskInputs, [quadrant]: e.target.value });
  };

  return (
    <div className="input-group mb-3">
      <input
        type="text"
        className="form-control"
        placeholder="Enter Task"
        value={taskInputs[quadrant]}
        onChange={handleInputChange}
        onKeyDown={(e) => e.key === "Enter" && addTask(quadrant)}
      />
      <button className="btn btn-primary" onClick={() => addTask(quadrant)}>
        Add
      </button>
    </div>
  );
};

export default TaskInput;
